using System.Globalization;
using System.Text;

namespace Jellyfin.Plugin.DualSubs.Services;

/// <summary>
/// Metadata stored in an ASS file generated by this plugin.
/// </summary>
/// <param name="Path">Absolute file path.</param>
/// <param name="Pair">Language pair, for example eng+spa.</param>
/// <param name="SourceHash">Hash of the source text and style configuration.</param>
/// <param name="OffsetMs">Applied offset.</param>
public sealed record PluginSubtitleFile(string Path, string Pair, string SourceHash, int OffsetMs);

/// <summary>
/// Reads the ownership marker of generated ASS files.
/// </summary>
public static class PluginFileDetector
{
    /// <summary>
    /// Ownership marker.
    /// </summary>
    public const string Marker = "; Generated by Jellyfin DualSubs";

    private const int HeaderLineCount = 24;

    /// <summary>
    /// Reads plugin metadata from a file. Returns null for files not written by this plugin.
    /// </summary>
    /// <param name="path">File path.</param>
    /// <returns>Metadata or null.</returns>
    public static PluginSubtitleFile? TryRead(string? path)
    {
        if (string.IsNullOrWhiteSpace(path) || !File.Exists(path))
        {
            return null;
        }

        try
        {
            using var reader = new StreamReader(path, Encoding.UTF8, detectEncodingFromByteOrderMarks: true);
            string? pair = null;
            string? hash = null;
            var offset = 0;
            var owned = false;

            for (var i = 0; i < HeaderLineCount; i++)
            {
                var line = reader.ReadLine();
                if (line is null)
                {
                    break;
                }

                if (line.StartsWith(Marker, StringComparison.Ordinal))
                {
                    owned = true;
                }
                else if (line.StartsWith("; DualSubs-Pair:", StringComparison.Ordinal))
                {
                    pair = line["; DualSubs-Pair:".Length..].Trim();
                }
                else if (line.StartsWith("; DualSubs-SourceHash:", StringComparison.Ordinal))
                {
                    hash = line["; DualSubs-SourceHash:".Length..].Trim();
                }
                else if (line.StartsWith("; DualSubs-OffsetMs:", StringComparison.Ordinal))
                {
                    int.TryParse(
                        line["; DualSubs-OffsetMs:".Length..].Trim(),
                        NumberStyles.Integer,
                        CultureInfo.InvariantCulture,
                        out offset);
                }
            }

            return owned && !string.IsNullOrEmpty(pair) && !string.IsNullOrEmpty(hash)
                ? new PluginSubtitleFile(path, pair, hash, offset)
                : null;
        }
        catch (IOException)
        {
            return null;
        }
        catch (UnauthorizedAccessException)
        {
            return null;
        }
    }

    /// <summary>
    /// Finds every plugin file that belongs to a video.
    /// </summary>
    /// <param name="video">Video item.</param>
    /// <returns>Plugin files, including ones not yet indexed as streams.</returns>
    public static IReadOnlyList<PluginSubtitleFile> FindForVideo(MediaBrowser.Controller.Entities.Video video)
    {
        ArgumentNullException.ThrowIfNull(video);

        var paths = new HashSet<string>(StringComparer.Ordinal);

        foreach (var stream in video.GetMediaStreams().Where(stream => stream.Type == MediaBrowser.Model.Entities.MediaStreamType.Subtitle && stream.IsExternal))
        {
            if (!string.IsNullOrWhiteSpace(stream.Path) && File.Exists(stream.Path))
            {
                paths.Add(stream.Path);
            }
        }

        var baseName = Path.GetFileNameWithoutExtension(video.Path);
        if (!string.IsNullOrEmpty(baseName))
        {
            foreach (var folder in CandidateFolders(video))
            {
                if (!Directory.Exists(folder))
                {
                    continue;
                }

                try
                {
                    foreach (var path in Directory.EnumerateFiles(folder, baseName + "*.ass"))
                    {
                        paths.Add(Path.GetFullPath(path));
                    }
                }
                catch (IOException)
                {
                    // Folder disappeared or is unreadable; streams above remain the source of truth.
                }
                catch (UnauthorizedAccessException)
                {
                    // Same: a read-only folder cannot be inspected, but the request can still report it.
                }
            }
        }

        return paths
            .Select(TryRead)
            .Where(file => file is not null)
            .Cast<PluginSubtitleFile>()
            .ToList();
    }

    private static IEnumerable<string> CandidateFolders(MediaBrowser.Controller.Entities.Video video)
    {
        if (!string.IsNullOrWhiteSpace(video.ContainingFolderPath))
        {
            yield return video.ContainingFolderPath;
        }

        string? metadataPath = null;
        try
        {
            metadataPath = video.GetInternalMetadataPath();
        }
        catch (InvalidOperationException)
        {
            // Some virtual items have no metadata path.
        }

        if (!string.IsNullOrWhiteSpace(metadataPath))
        {
            yield return metadataPath;
        }
    }
}
